<template>
  <div class="workflow-page" :class="{ 'is-editor': editorMode }">
    <header v-if="!editorMode" class="script-toolbar">
      <el-input
        v-model="workflowSearchInput"
        clearable
        aria-label="搜索工作流"
        placeholder="搜索工作流名称或描述"
        class="script-search"
        @keyup.enter="searchWorkflows"
        @clear="searchWorkflows"
      >
        <template #append>
          <el-button aria-label="搜索" @click="searchWorkflows"><el-icon><Search /></el-icon></el-button>
        </template>
      </el-input>
      <div class="script-toolbar-actions">
        <el-button :icon="Refresh" :loading="loading" @click="loadData">刷新</el-button>
        <el-button type="primary" :icon="Plus" @click="openCreate" v-permission="['workflow:create']">创建</el-button>
      </div>
    </header>

    <el-table v-if="!editorMode" :data="filteredWorkflows" v-loading="loading" stripe>
      <el-table-column label="工作流" min-width="210"><template #default="{ row }"><div class="workflow-name"><strong>{{ row.name }}</strong><small>{{ row.description || '暂无说明' }}</small></div></template></el-table-column>
      <el-table-column label="步骤" min-width="270"><template #default="{ row }"><div class="step-summary"><span v-for="(step, index) in parseSteps(row.steps).slice(0, 4)" :key="index">{{ stepTypeMeta(step.type).short }}</span><em v-if="parseSteps(row.steps).length > 4">+{{ parseSteps(row.steps).length - 4 }}</em></div></template></el-table-column>
      <el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status === 1 ? 'success' : 'info'" size="small">{{ row.status === 1 ? '已启用' : '已停用' }}</el-tag></template></el-table-column>
      <el-table-column label="操作" width="210" fixed="right"><template #default="{ row }"><el-button link type="success" :loading="runId === row.id" @click="runOne(row)" v-permission="['workflow:run']">立即执行</el-button><el-button link type="primary" @click="openEdit(row)" v-permission="['workflow:edit']">编辑</el-button><el-button link type="danger" @click="removeOne(row)" v-permission="['workflow:delete']">删除</el-button></template></el-table-column>
      <template #empty><TableEmpty /></template>
    </el-table>

    <div v-else class="workflow-editor-page">
      <div class="preview-header">
        <el-button link type="primary" :icon="ArrowLeft" @click="closeEditor">返回</el-button>
      </div>
      <div class="workflow-studio workflow-studio-page">
        <div class="studio-shell">
        <div class="studio-grid">
          <aside class="node-library">
            <div class="flow-options">
              <label>名称<span class="required-mark" aria-hidden="true">*</span></label><el-input v-model="form.name" maxlength="100" aria-required="true" placeholder="请输入工作流名称" />
              <label class="description-label">说明</label><el-input v-model="form.description" type="textarea" :rows="3" placeholder="这个流程用来做什么" />
            </div>
            <div class="panel-title"><strong>节点库</strong><el-tooltip content="点击节点添加，或将节点拖入画布" placement="right"><span class="panel-help" tabindex="0" aria-label="节点库使用说明"><el-icon><InfoFilled /></el-icon></span></el-tooltip></div>
            <button v-for="item in paletteStepTypes" :key="item.value" type="button" class="palette-node" draggable="true" @dragstart="startPaletteDrag(item.value, $event)" @click="addStep(item.value)">
              <span class="palette-badge">{{ item.short.slice(0, 1) }}</span><span><b>{{ item.label }}</b><small>{{ item.short }}</small></span><el-icon><Plus /></el-icon>
            </button>
            <div class="enable-row"><span><b>启用工作流</b><el-tooltip content="停用后不可执行" placement="right"><span class="panel-help" tabindex="0" aria-label="启用状态说明"><el-icon><InfoFilled /></el-icon></span></el-tooltip></span><el-switch v-model="form.status" :active-value="1" :inactive-value="0" /></div>
          </aside>

          <main class="canvas-panel" @drop.prevent="dropOnCanvas" @dragover.prevent>
            <div class="canvas-tip"><el-icon><InfoFilled /></el-icon>从节点端口拖线连接；开始节点可连接多条并行分支</div>
            <workflow-canvas :steps="steps" :selected-index="selectedStepIndex" :step-meta="stepTypeMeta" :summaries="steps.map(nodeSummary)" @select="selectedStepIndex = $event" @connect="connectNodes" @disconnect="disconnectNodes" @move="moveNode" />
            <button v-if="!steps.length" type="button" class="empty-canvas flow-empty" @click="addStep('script')"><el-icon><Plus /></el-icon><strong>添加第一个节点</strong><span>也可以从左侧拖入</span></button>
          </main>

          <aside class="property-panel">
            <template v-if="selectedStep">
              <div class="property-title"><span><b>节点配置</b><small>步骤 {{ selectedStepIndex + 1 }}</small></span><el-button text type="danger" @click="removeStep(selectedStepIndex)"><el-icon><Delete /></el-icon></el-button></div>
              <el-form label-position="top" class="property-form">
                <el-form-item label="节点类型"><el-select v-model="selectedStep.type" @change="resetStep(selectedStepIndex, selectedStep.type)"><el-option v-for="item in editableStepTypes" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item>
                <el-form-item label="节点名称"><el-input v-model="selectedStep.name" :placeholder="stepTypeMeta(selectedStep.type).label" /></el-form-item>
                <el-form-item><template #label><span>节点标识 <el-tooltip content="后续节点通过 {{ steps.节点标识.output }} 引用该节点输出" placement="top"><el-icon><InfoFilled /></el-icon></el-tooltip></span></template><el-input v-model="selectedStep.key" placeholder="例如 check_result" @focus="editingStepKey = selectedStep.key" @change="renameStepKey(editingStepKey, selectedStep.key)" /></el-form-item>
                <el-form-item v-if="selectedStep.type === 'script'" label="选择脚本"><el-select v-model="selectedStep.id" filterable placeholder="从脚本库选择"><el-option v-for="script in activeScripts" :key="script.id" :label="script.name" :value="script.id" /></el-select></el-form-item>
                <el-form-item v-if="selectedStep.type === 'script'"><template #label><span>输入参数 <el-tooltip content="支持 {{ input.alert.target }} 或 {{ steps.check.output }}；脚本中读取 AIOPS_STEP_INPUT，完整上下文读取 AIOPS_WORKFLOW_CONTEXT" placement="top"><el-icon><InfoFilled /></el-icon></el-tooltip></span></template><el-input v-model="selectedStep.input" type="textarea" :rows="3" placeholder='例如 {"target":"{{ input.alert.target }}"}' /></el-form-item>
                <el-form-item v-if="selectedStep.type === 'script'" label="执行节点"><node-select v-model="selectedStep.node_value" :ssh-nodes="sshNodes" :agent-nodes="agentNodes" /></el-form-item>
                <template v-if="selectedStep.type === 'condition'"><el-form-item><template #label><span>判断对象 <el-tooltip content="选择上游节点状态或输出；也可以直接输入 steps.变量名.output.字段" placement="top"><el-icon><InfoFilled /></el-icon></el-tooltip></span></template><el-select v-model="selectedStep.condition_path" filterable allow-create default-first-option placeholder="选择上游节点，或输入变量路径" @change="handleConditionSourceChange"><el-option v-for="item in conditionSourceOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><div v-if="!conditionSourceOptions.length" class="condition-source-empty">请先把上游节点连接到当前判断节点，也可以直接输入自定义变量路径</div><el-form-item label="判断方式"><el-select v-model="selectedStep.condition_operator"><el-option v-for="item in conditionOperators" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item v-if="!['exists','not_exists','truthy'].includes(selectedStep.condition_operator)" label="比较值"><el-input v-model="selectedStep.condition_value" :placeholder="selectedStep.condition_path.endsWith('.status') ? 'success' : '例如 critical'" /></el-form-item><div class="branch-status"><span class="true"><b>成功</b>{{ branchTargetName(selectedStep.true_next) }}</span><span class="false"><b>失败</b>{{ branchTargetName(selectedStep.false_next) }}</span><small>请从画布上 IF 节点左右两侧的成功 / 失败端口拖线连接</small></div></template>
                <template v-if="selectedStep.type === 'end'"><el-form-item label="流程结果"><el-select v-model="selectedStep.result_status"><el-option label="成功" value="success" /><el-option label="失败" value="fail" /></el-select></el-form-item><el-form-item><template #label><span>最终输出 <el-tooltip content="可留空；支持 {{ steps.节点标识.output }} 等模板变量" placement="top"><el-icon><InfoFilled /></el-icon></el-tooltip></span></template><el-input v-model="selectedStep.input" type="textarea" :rows="4" placeholder="例如 {{ steps.deploy.output }}" /></el-form-item></template>
              </el-form>
            </template>
            <div v-else class="property-empty"><el-icon><Pointer /></el-icon><strong>选择一个节点</strong><span>点击画布节点后在这里配置参数</span></div>
          </aside>
        </div>
      </div>
      </div>
      <editor-action-bar>
        <template #leading><span class="editor-action-hint">自由编排 · {{ steps.length }} 个节点</span></template>
        <el-button @click="closeEditor">取消</el-button>
        <el-button type="primary" :loading="saving" @click="saveWorkflow">{{ form.id ? '保存修改' : '创建工作流' }}</el-button>
      </editor-action-bar>
    </div>

    <el-dialog v-if="!editorMode" v-model="runVisible" class="workflow-run-dialog" title="工作流执行轨迹" width="min(820px, 92vw)">
      <div v-if="runResult" class="run-summary" :class="runResult.status === 'success' ? 'success' : 'failed'"><strong>{{ runResult.status === 'success' ? '工作流执行成功' : '工作流执行未完成' }}</strong><span>总耗时 {{ runResult.duration_ms }}ms，共执行 {{ runSteps.length }} 个步骤</span></div>
      <div class="run-flow"><template v-for="(step, index) in runSteps" :key="index"><article class="run-node" :class="step.status === 'success' ? 'success' : 'failed'"><el-icon><component :is="step.status === 'success' ? CircleCheckFilled : CircleCloseFilled" /></el-icon><span><small>节点 {{ String(step.step).padStart(2, '0') }} · {{ stepTypeMeta(step.type).short }}</small><strong>{{ step.name }}</strong><em>{{ step.status === 'success' ? '执行成功' : '执行失败' }} · {{ step.duration_ms }}ms</em></span><pre>{{ step.result || '没有返回内容' }}</pre></article><div v-if="index < runSteps.length - 1" class="run-line"></div></template></div>
      <template #footer><el-button @click="runVisible = false">关闭</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, CircleCheckFilled, CircleCloseFilled, Delete, InfoFilled, Plus, Pointer, Refresh, Search } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox, ElOption, ElOptionGroup, ElSelect } from 'element-plus'
import { createWorkflow, deleteWorkflow, getWorkflows, runWorkflow, updateWorkflow } from '../../api/workflow'
import { getScripts } from '../../api/script'
import { getAgents, getCertificateExecutors } from '../../api/certificate'
import EditorActionBar from '../../components/EditorActionBar.vue'
import WorkflowCanvas from '../../components/workflow/WorkflowCanvas.vue'

const NodeSelect = defineComponent({ name: 'NodeSelect', props: { modelValue: { type: String, default: 'direct' }, sshNodes: { type: Array, default: () => [] }, agentNodes: { type: Array, default: () => [] } }, emits: ['update:modelValue'], setup(props, { emit }) { return () => h(ElSelect, { modelValue: props.modelValue, 'onUpdate:modelValue': value => emit('update:modelValue', value) }, { default: () => [h(ElOption, { label: '服务端直连', value: 'direct' }), props.sshNodes.length ? h(ElOptionGroup, { label: 'SSH 节点' }, { default: () => props.sshNodes.map(node => h(ElOption, { label: node.name, value: `ssh:${node.id}`, disabled: node.status !== 1 })) }) : null, props.agentNodes.length ? h(ElOptionGroup, { label: 'Agent 节点' }, { default: () => props.agentNodes.map(node => h(ElOption, { label: node.name, value: `agent:${node.id}` })) }) : null] }) } })

const stepTypes = [
  { value: 'script', label: '执行脚本', short: 'SCRIPT', description: '运行脚本库中的 Shell 或 Python 脚本' },
  { value: 'condition', label: '条件判断', short: 'IF', description: '根据输入或步骤输出决定后续执行' },
  { value: 'end', label: '结束', short: 'END', description: '声明工作流最终状态和输出' },
]
const conditionOperators = [{ label: '等于', value: 'equals' }, { label: '不等于', value: 'not_equals' }, { label: '包含', value: 'contains' }, { label: '存在', value: 'exists' }, { label: '不存在', value: 'not_exists' }, { label: '为真', value: 'truthy' }, { label: '大于', value: 'greater_than' }, { label: '小于', value: 'less_than' }]
const paletteStepTypes = stepTypes
const route = useRoute(), router = useRouter()
const workflows = ref([]), scripts = ref([]), sshNodes = ref([]), agentNodes = ref([])
const workflowSearchInput = ref(''), workflowKeyword = ref('')
const loading = ref(false), saving = ref(false), steps = ref([])
const form = reactive({ id: null, name: '', description: '', status: 1 })
const activeScripts = ref([])
const runId = ref(null), runVisible = ref(false), runResult = ref(null), runSteps = ref([])
const selectedStepIndex = ref(-1)
const editingStepKey = ref('')
const selectedStep = computed(() => steps.value[selectedStepIndex.value] || null)
const editableStepTypes = stepTypes
const conditionSourceOptions = computed(() => { if (selectedStep.value?.type !== 'condition') return []; const targetKey = selectedStep.value.key; return steps.value.filter(step => outgoingKeys(step).includes(targetKey)).flatMap(step => { const name = step.name || stepTypeMeta(step.type).label; return [{ label: `${name} · 执行状态`, value: `steps.${step.key}.status` }, { label: `${name} · 输出内容`, value: `steps.${step.key}.output` }] }) })
const editorMode = computed(() => route.name === 'WorkflowCreate' || route.name === 'WorkflowEdit')
const filteredWorkflows = computed(() => {
  const keyword = workflowKeyword.value.trim().toLowerCase()
  if (!keyword) return workflows.value
  return workflows.value.filter(item => [item.name, item.description].some(value => String(value || '').toLowerCase().includes(keyword)))
})

onMounted(loadData)
watch(() => route.fullPath, async () => {
  if (!editorMode.value) return
  if (!workflows.value.length) await loadData()
  else initializeEditor()
})
async function loadData() {
  loading.value = true
  try {
    const results = await Promise.allSettled([getWorkflows(), getScripts(), getCertificateExecutors(), getAgents()])
    if (results[0].status === 'fulfilled') workflows.value = results[0].value.data || []
    if (results[1].status === 'fulfilled') scripts.value = results[1].value.data || []
    if (results[2].status === 'fulfilled') sshNodes.value = results[2].value.data || []
    if (results[3].status === 'fulfilled') agentNodes.value = results[3].value.data || []
    activeScripts.value = scripts.value.filter(item => item.status === 1)
    if (editorMode.value) initializeEditor()
  } finally { loading.value = false }
}
function searchWorkflows() { workflowKeyword.value = workflowSearchInput.value }
function stepTypeMeta(type) { return stepTypes.find(item => item.value === type) || { value: type, label: type, short: String(type || '?').toUpperCase(), description: '' } }
function nextStepKey() { let index = steps.value.length + 1; while (steps.value.some(step => step.key === `step_${index}`)) index++; return `step_${index}` }
function defaultStep(type = 'script', key = '') { return { key: key || nextStepKey(), type, name: '', id: null, node_value: 'direct', timeout_ms: 10000, input: '', condition_path: '', condition_operator: 'equals', condition_value: '', result_status: 'success', true_next: '', false_next: '', next: [], start: false, graph_version: 2, position: null } }
function defaultNodePosition(index) { return { x: 60 + (index % 2) * 310, y: 135 + Math.floor(index / 2) * 155 } }
function addStep(type) { const step = defaultStep(type); step.position = defaultNodePosition(steps.value.length); steps.value.push(step); selectedStepIndex.value = steps.value.length - 1 }
function removeStep(index) { const removedKey = steps.value[index]?.key; if (!removedKey) return; steps.value.forEach(step => { step.next = (step.next || []).filter(target => target !== removedKey); if (step.true_next === removedKey) step.true_next = ''; if (step.false_next === removedKey) step.false_next = '' }); steps.value.splice(index, 1); selectedStepIndex.value = Math.min(index, steps.value.length - 1) }
function resetStep(index, type) { const previous = steps.value[index]; const replacement = { ...defaultStep(type, previous.key), name: previous.name, start: previous.start, position: previous.position }; if (type === 'condition') { const targets = previous.type === 'condition' ? [previous.true_next, previous.false_next] : (previous.next || []); replacement.true_next = targets[0] || ''; replacement.false_next = targets[1] || '' } else if (type !== 'end') replacement.next = previous.type === 'condition' ? [...new Set([previous.true_next, previous.false_next].filter(Boolean))] : [...(previous.next || [])]; steps.value[index] = replacement }
function openCreate() { router.push('/automation/workflows/create') }
function openEdit(row) { router.push(`/automation/workflows/${row.id}/edit`) }
function closeEditor() { router.push('/automation/workflows') }
function initializeEditor() {
  const row = route.name === 'WorkflowEdit' ? workflows.value.find(item => item.id === Number(route.params.id)) : null
  if (route.name === 'WorkflowEdit' && !row) { ElMessage.error('工作流不存在'); closeEditor(); return }
  Object.assign(form, row
    ? { id: row.id, name: row.name, description: row.description || '', status: row.status }
    : { id: null, name: '', description: '', status: 1 })
  const storedSteps = row ? parseSteps(row.steps) : []
  steps.value = storedSteps.map((step, index) => stepFromAPI(step, index))
  selectedStepIndex.value = steps.value.length ? 0 : -1
}
function parseSteps(raw) { try { const value = JSON.parse(raw || '[]'); return Array.isArray(value) ? value : [] } catch { return [] } }
function stepFromAPI(step, index) { return { ...defaultStep(step.type, step.key), ...step, next: Array.isArray(step.next) ? step.next : [], true_next: step.true_next || '', false_next: step.false_next || '', position: step.position || defaultNodePosition(index), node_value: step.node_type && step.node_type !== 'direct' ? `${step.node_type}:${step.node_id}` : 'direct' } }
function buildSteps() { return steps.value.map(step => { const [nodeType, rawNodeID] = step.node_value.includes(':') ? step.node_value.split(':') : ['direct', '0']; const base = { key: step.key.trim(), type: step.type, name: step.name.trim(), graph_version: 2, start: Boolean(step.start), next: step.type === 'condition' ? [] : [...(step.next || [])], position: step.position }; if (step.type === 'script') Object.assign(base, { id: step.id, input: step.input, node_type: nodeType, node_id: Number(rawNodeID) || 0, timeout_ms: step.timeout_ms }); if (step.type === 'condition') Object.assign(base, { condition_path: step.condition_path.trim(), condition_operator: step.condition_operator, condition_value: step.condition_value, true_next: step.true_next, false_next: step.false_next }); if (step.type === 'end') Object.assign(base, { input: step.input, result_status: step.result_status }); return base }) }
function validateSteps() { if (!form.name.trim()) return '请输入工作流名称'; if (!steps.value.length) return '请至少添加一个执行节点'; const keys = steps.value.map(step => step.key.trim()); const uniqueKeys = new Set(); const adjacency = steps.value.map(() => []); const indegree = steps.value.map(() => 0); for (let index = 0; index < steps.value.length; index++) { const step = steps.value[index]; if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(keys[index])) return `第 ${index + 1} 个节点的输出变量名不正确`; if (uniqueKeys.has(keys[index])) return `第 ${index + 1} 个节点的输出变量名重复`; uniqueKeys.add(keys[index]); if (step.type === 'script' && !step.id) return `第 ${index + 1} 个节点还没有选择执行对象`; if (step.type === 'condition' && !step.condition_path.trim()) return `第 ${index + 1} 个条件节点还没有填写变量路径`; const targets = step.type === 'condition' ? [step.true_next, step.false_next] : (step.next || []); if (step.type === 'condition' && targets.some(target => !target)) return `第 ${index + 1} 个条件节点的 TRUE 和 FALSE 端口都需要连线`; for (const target of targets) { const targetIndex = keys.indexOf(target); if (targetIndex < 0) return `第 ${index + 1} 个节点存在失效连线`; if (targetIndex === index) return `第 ${index + 1} 个节点不能连接自己`; adjacency[index].push(targetIndex); indegree[targetIndex]++ } } if (!steps.value.some(step => step.start)) return '请从开始节点至少连接一个执行节点'; for (let index = 0; index < steps.value.length; index++) if (steps.value[index].start && indegree[index]) return `第 ${index + 1} 个节点不能同时连接开始节点和其他上游节点`; const state = steps.value.map(() => 0); const visit = index => { if (state[index] === 1) return false; if (state[index] === 2) return true; state[index] = 1; if (adjacency[index].some(target => !visit(target))) return false; state[index] = 2; return true }; if (steps.value.some((_, index) => !visit(index))) return '工作流不能包含循环连线'; const reachable = new Set(); const mark = index => { if (reachable.has(index)) return; reachable.add(index); adjacency[index].forEach(mark) }; steps.value.forEach((step, index) => { if (step.start) mark(index) }); if (reachable.size !== steps.value.length) return '存在尚未连接到开始节点的节点'; return '' }
function validateAutomationShape() { if (!steps.value.some(step => step.type === 'end')) return ''; const openStep = steps.value.find(step => step.type !== 'end' && outgoingKeys(step).length === 0); return openStep ? `节点「${openStep.name || stepTypeMeta(openStep.type).label}」必须连接结束节点` : '' }
async function saveWorkflow() { const error = validateAutomationShape() || validateSteps(); if (error) return ElMessage.warning(error); saving.value = true; try { const payload = { ...form, name: form.name.trim(), steps: JSON.stringify(buildSteps()) }; form.id ? await updateWorkflow(form.id, payload) : await createWorkflow(payload); ElMessage.success(form.id ? '工作流已更新' : '工作流已创建'); await loadData(); closeEditor() } finally { saving.value = false } }
async function removeOne(row) { await ElMessageBox.confirm(`确定删除工作流「${row.name}」吗？`, '提示', { type: 'warning' }); await deleteWorkflow(row.id); ElMessage.success('已删除'); loadData() }
async function runOne(row) { runId.value = row.id; try { const response = await runWorkflow(row.id); runResult.value = response.data; runSteps.value = parseSteps(response.data.result); runVisible.value = true } finally { runId.value = null } }
function nodeSummary(step) { if (step.type === 'script') return activeScripts.value.find(item => item.id === step.id)?.name || '请选择脚本'; if (step.type === 'condition') return step.condition_path ? `${step.condition_path} ${conditionOperators.find(item => item.value === step.condition_operator)?.label || ''} ${step.condition_value}` : '请配置判断条件'; if (step.type === 'end') return `${step.result_status === 'success' ? '成功' : '失败'}结束${step.input ? ` · ${step.input}` : ''}`; return '' }
function nodeIndexFromID(id) { const match = /^step-(\d+)$/.exec(String(id || '')); return match ? Number(match[1]) : -1 }
function outgoingKeys(step) { return step.type === 'condition' ? [step.true_next, step.false_next].filter(Boolean) : (step.next || []) }
